import Flutter
import UIKit
import WidgetKit

/// The Dart side's door to the App Group store shared with the widget
/// extension, and the relay for widget taps.
///
/// The extension (generated by `dart run live_timer_widget:setup_ios`) reads
/// the state JSON under `stateKey` and the images under `imagesDir` — keep
/// these in sync with its `LiveTimerWidget.swift`.
public class LiveTimerWidgetPlugin: NSObject, FlutterPlugin, FlutterStreamHandler,
  FlutterSceneLifeCycleDelegate
{
  static let stateKey = "live_timer_widget.state"
  static let imagesDir = "live_timer_widget"
  /// Taps open the app with `livetimerwidget://tap?target=…&link=…`.
  static let tapScheme = "livetimerwidget"

  // Remembered in the app's own defaults so a background engine (a push
  // handler) can write without calling `initialize` again.
  private static let appGroupKey = "live_timer_widget.appGroupId"
  private static let kindKey = "live_timer_widget.widgetKind"

  private var sink: FlutterEventSink?
  private var initialTap: [String: Any]?
  /// File work stays off the platform thread, in call order.
  private let io = DispatchQueue(label: "live_timer_widget.io")

  public static func register(with registrar: FlutterPluginRegistrar) {
    let instance = LiveTimerWidgetPlugin()
    let channel = FlutterMethodChannel(
      name: "live_timer_widget", binaryMessenger: registrar.messenger())
    registrar.addMethodCallDelegate(instance, channel: channel)
    FlutterEventChannel(name: "live_timer_widget/taps", binaryMessenger: registrar.messenger())
      .setStreamHandler(instance)
    registrar.addApplicationDelegate(instance)
    registrar.addSceneDelegate(instance)
  }

  private var appGroupId: String? { UserDefaults.standard.string(forKey: Self.appGroupKey) }

  private var kind: String {
    UserDefaults.standard.string(forKey: Self.kindKey) ?? "LiveTimerWidget"
  }

  private var store: UserDefaults? { appGroupId.flatMap { UserDefaults(suiteName: $0) } }

  /// `nil` when the App Group isn't in the app's entitlements.
  private var imagesURL: URL? {
    guard let appGroupId,
      let container = FileManager.default.containerURL(
        forSecurityApplicationGroupIdentifier: appGroupId)
    else { return nil }
    let url = container.appendingPathComponent(Self.imagesDir, isDirectory: true)
    try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    return url
  }

  public func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
    let args = call.arguments as? [String: Any] ?? [:]
    switch call.method {
    case "initialize":
      if let group = args["appGroupId"] as? String, !group.isEmpty {
        UserDefaults.standard.set(group, forKey: Self.appGroupKey)
      }
      if let kind = args["widgetKind"] as? String, !kind.isEmpty {
        UserDefaults.standard.set(kind, forKey: Self.kindKey)
      }
      guard imagesURL != nil else {
        return result(
          FlutterError(
            code: "no_app_group",
            message: "Pass iOSAppGroupId to LiveTimerWidget.initialize, and add that App Group "
              + "to the Runner and widget extension entitlements (setup_ios does both).",
            details: appGroupId))
      }
      result(nil)

    case "load":
      result(store?.string(forKey: Self.stateKey))

    case "save":
      guard let store else { return result(notInitialized) }
      store.set(args["state"] as? String, forKey: Self.stateKey)
      WidgetCenter.shared.reloadTimelines(ofKind: kind)
      result(nil)

    case "hasImage":
      guard let url = imageURL(args["name"]) else { return result(false) }
      result(FileManager.default.fileExists(atPath: url.path))

    case "saveImage":
      guard let url = imageURL(args["name"]),
        let bytes = args["bytes"] as? FlutterStandardTypedData
      else { return result(notInitialized) }
      io.async {
        do {
          try bytes.data.write(to: url, options: .atomic)
          DispatchQueue.main.async { result(nil) }
        } catch {
          DispatchQueue.main.async {
            result(FlutterError(code: "live_timer_widget", message: "\(error)", details: nil))
          }
        }
      }

    case "pruneImages":
      let keep = Set(args["keep"] as? [String] ?? [])
      guard let dir = imagesURL else { return result(nil) }
      io.async {
        let files =
          (try? FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil))
          ?? []
        for file in files where !keep.contains(file.lastPathComponent) {
          try? FileManager.default.removeItem(at: file)
        }
        DispatchQueue.main.async { result(nil) }
      }

    case "installedCount":
      let kind = self.kind
      WidgetCenter.shared.getCurrentConfigurations { configs in
        let count = (try? configs.get())?.filter { $0.kind == kind }.count ?? 0
        DispatchQueue.main.async { result(count) }
      }

    // iOS has no API to place a widget for the user.
    case "isPinSupported", "requestPin":
      result(false)

    case "initialTap":
      result(initialTap)
      initialTap = nil

    default:
      result(FlutterMethodNotImplemented)
    }
  }

  private var notInitialized: FlutterError {
    FlutterError(
      code: "not_initialized",
      message: "Call LiveTimerWidget.initialize(iOSAppGroupId: …) first.", details: nil)
  }

  /// Only a bare file name: the Dart side never picks the directory.
  private func imageURL(_ name: Any?) -> URL? {
    guard let name = name as? String, !name.isEmpty, let dir = imagesURL else { return nil }
    return dir.appendingPathComponent((name as NSString).lastPathComponent)
  }

  // MARK: - Taps

  public func onListen(withArguments arguments: Any?, eventSink events: @escaping FlutterEventSink)
    -> FlutterError?
  {
    sink = events
    return nil
  }

  public func onCancel(withArguments arguments: Any?) -> FlutterError? {
    sink = nil
    return nil
  }

  /// `{link, target}` for a widget tap URL, `nil` for any other URL.
  static func tap(from url: URL) -> [String: Any]? {
    guard url.scheme == tapScheme,
      let components = URLComponents(url: url, resolvingAgainstBaseURL: false)
    else { return nil }
    var query: [String: String] = [:]
    for item in components.queryItems ?? [] where query[item.name] == nil {
      query[item.name] = item.value ?? ""
    }
    let link = query["link"] ?? ""
    return [
      "link": link.isEmpty ? NSNull() : link,
      "target": query["target"] ?? "widget",
    ]
  }

  /// A tap while running goes to the stream; one that launched the app waits
  /// for `initialTap`. Returning true keeps Flutter's deep linking off it.
  private func handle(url: URL, launching: Bool) -> Bool {
    guard let tap = Self.tap(from: url) else { return false }
    if launching || sink == nil {
      initialTap = tap
    } else {
      sink?(tap)
    }
    return true
  }

  // App delegate (apps without scenes)

  public func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [AnyHashable: Any] = [:]
  ) -> Bool {
    if let url = launchOptions[UIApplication.LaunchOptionsKey.url] as? URL {
      _ = handle(url: url, launching: true)
    }
    return true
  }

  public func application(
    _ app: UIApplication, open url: URL, options: [UIApplication.OpenURLOptionsKey: Any] = [:]
  ) -> Bool {
    handle(url: url, launching: false)
  }

  // Scene delegate (apps with scenes)

  /// Never claims the connection, so other plugins still see its options.
  public func scene(
    _ scene: UIScene, willConnectTo session: UISceneSession,
    options connectionOptions: UIScene.ConnectionOptions?
  ) -> Bool {
    for context in connectionOptions?.urlContexts ?? [] {
      _ = handle(url: context.url, launching: true)
    }
    return false
  }

  public func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) -> Bool {
    var handled = false
    for context in URLContexts {
      handled = handle(url: context.url, launching: false) || handled
    }
    return handled
  }
}
